CREATE OR REPLACE FUNCTION public.add_credits_for_payment(p_user_id uuid, p_amount numeric, p_credits bigint, p_plan text, p_razorpay_order_id text, p_razorpay_payment_id text, p_razorpay_signature text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_inserted_id uuid;
  v_balance     bigint;
begin
  if p_user_id is null then
    raise exception 'add_credits_for_payment: user_id is required';
  end if;
  if p_credits is null or p_credits <= 0 then
    raise exception 'add_credits_for_payment: credits must be positive';
  end if;
  if p_razorpay_payment_id is null or length(p_razorpay_payment_id) = 0 then
    raise exception 'add_credits_for_payment: razorpay_payment_id is required';
  end if;

  -- Step 1: idempotent payment insert
  insert into public.payments (
    user_id,
    plan,
    amount,
    credits_added,
    status,
    razorpay_order_id,
    razorpay_payment_id,
    razorpay_signature
  ) values (
    p_user_id,
    p_plan,
    p_amount,
    p_credits,
    'paid',
    p_razorpay_order_id,
    p_razorpay_payment_id,
    p_razorpay_signature
  )
  on conflict (razorpay_payment_id) do nothing
  returning id into v_inserted_id;

  if v_inserted_id is null then
    -- Duplicate payment_id → already processed. No change.
    select credits into v_balance
      from public.profiles
     where id = p_user_id;

    return jsonb_build_object(
      'added',         false,
      'credits_added', 0,
      'new_balance',   coalesce(v_balance, 0)
    );
  end if;

  -- Step 2: atomic credit increment + plan set
  update public.profiles
     set credits    = credits + p_credits,
         plan       = p_plan,
         updated_at = now()
   where id = p_user_id
   returning credits into v_balance;

  if v_balance is null then
    -- Profile must exist; rollback the whole transaction.
    raise exception 'add_credits_for_payment: profile % not found', p_user_id;
  end if;

  -- Step 3: audit trail
  insert into public.credit_transactions(
    user_id, delta, reason, generation_id, balance_after
  ) values (
    p_user_id,
    p_credits,
    'payment:' || coalesce(p_plan, 'unknown'),
    p_razorpay_payment_id,
    v_balance
  );

  return jsonb_build_object(
    'added',         true,
    'credits_added', p_credits,
    'new_balance',   v_balance
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.add_credits_for_payment(p_user_id uuid, p_amount numeric, p_credits bigint, p_plan text, p_razorpay_order_id text, p_razorpay_payment_id text, p_razorpay_signature text, p_billing_name text DEFAULT NULL::text, p_billing_phone text DEFAULT NULL::text, p_billing_email text DEFAULT NULL::text, p_billing_company text DEFAULT NULL::text, p_billing_address text DEFAULT NULL::text, p_billing_gstin text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_inserted_id uuid;
  v_balance     bigint;
begin
  if p_user_id is null then
    raise exception 'add_credits_for_payment: user_id is required';
  end if;
  if p_credits is null or p_credits <= 0 then
    raise exception 'add_credits_for_payment: credits must be positive';
  end if;
  if p_razorpay_payment_id is null or length(p_razorpay_payment_id) = 0 then
    raise exception 'add_credits_for_payment: razorpay_payment_id is required';
  end if;

  insert into public.payments (
    user_id, plan, amount, credits_added, status,
    razorpay_order_id, razorpay_payment_id, razorpay_signature,
    billing_name, billing_phone, billing_email,
    billing_company, billing_address, billing_gstin
  ) values (
    p_user_id, p_plan, p_amount, p_credits, 'paid',
    p_razorpay_order_id, p_razorpay_payment_id, p_razorpay_signature,
    p_billing_name, p_billing_phone, p_billing_email,
    p_billing_company, p_billing_address, p_billing_gstin
  )
  on conflict (razorpay_payment_id) do nothing
  returning id into v_inserted_id;

  if v_inserted_id is null then
    select credits into v_balance
      from public.profiles where id = p_user_id;
    return jsonb_build_object(
      'added',         false,
      'credits_added', 0,
      'new_balance',   coalesce(v_balance, 0)
    );
  end if;

  -- Profile update — credits + plan + subscription window +
  -- latest billing details cache (only when caller sent them).
  update public.profiles
     set credits             = credits + p_credits,
         plan                = p_plan,
         plan_purchased_at   = now(),
         plan_expires_at     = now() + interval '30 days',
         last_renewal_alert_at = null,
         billing_name        = coalesce(p_billing_name,    billing_name),
         billing_phone       = coalesce(p_billing_phone,   billing_phone),
         billing_company     = coalesce(p_billing_company, billing_company),
         billing_address     = coalesce(p_billing_address, billing_address),
         billing_gstin       = coalesce(p_billing_gstin,   billing_gstin),
         updated_at          = now()
   where id = p_user_id
   returning credits into v_balance;

  if v_balance is null then
    raise exception 'add_credits_for_payment: profile % not found', p_user_id;
  end if;

  insert into public.credit_transactions(
    user_id, delta, reason, generation_id, balance_after
  ) values (
    p_user_id,
    p_credits,
    'payment:' || coalesce(p_plan, 'unknown'),
    p_razorpay_payment_id,
    v_balance
  );

  return jsonb_build_object(
    'added',         true,
    'credits_added', p_credits,
    'new_balance',   v_balance
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.has_permission(p_perm text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_perms text[];
  v_prefix text;
begin
  v_perms := public.current_user_permissions();
  if v_perms is null then return false; end if;
  if '*' = any(v_perms) then return true; end if;
  if p_perm = any(v_perms) then return true; end if;

  -- Wildcard on prefix, e.g. permission 'leads.*' grants any
  -- 'leads.xxx' check.
  v_prefix := split_part(p_perm, '.', 1) || '.*';
  if v_prefix = any(v_perms) then return true; end if;

  return false;
end;
$function$

CREATE OR REPLACE FUNCTION public.profiles_block_credit_tampering()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if current_user in ('service_role', 'postgres', 'supabase_admin') then
    return new;
  end if;

  if (
    new.credits is distinct from old.credits
    or new.plan is distinct from old.plan
  ) then
    raise exception
      'credits/plan cannot be modified from the client. '
      'Use deduct_credits()/refund_credits() server-side instead.';
  end if;

  if (
    new.id                         is distinct from old.id
    or new.is_unlimited            is distinct from old.is_unlimited
    or new.plan_expires_at         is distinct from old.plan_expires_at
    or new.plan_purchased_at       is distinct from old.plan_purchased_at
    or new.last_renewal_alert_at   is distinct from old.last_renewal_alert_at
    or new.referral_code           is distinct from old.referral_code
    or new.referral_credits_earned is distinct from old.referral_credits_earned
    or new.health_score            is distinct from old.health_score
    or new.health_status           is distinct from old.health_status
    or new.health_computed_at      is distinct from old.health_computed_at
    or new.created_at              is distinct from old.created_at
  ) then
    raise exception 'This profile field cannot be modified from the client.';
  end if;

  if old.referred_by is not null
     and new.referred_by is distinct from old.referred_by then
    raise exception 'referred_by can only be set once.';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.profiles_guard_client_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if current_user in ('service_role', 'postgres', 'supabase_admin') then
    return new;
  end if;

  new.credits := least(greatest(coalesce(new.credits, 0), 0), 100);
  if lower(coalesce(new.plan, 'free')) <> 'free' then
    new.plan := 'free';
  end if;
  new.is_unlimited            := false;
  new.plan_expires_at         := null;
  new.plan_purchased_at       := null;
  new.referral_code           := null;
  new.referral_credits_earned := 0;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_referral_earning(p_user_id uuid, p_order_id text, p_amount numeric, p_payment_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_code text;
  v_cid  uuid;
  v_pct  numeric := 10;          -- FIXED 10% commission
  v_comm numeric;
begin
  if p_user_id is null then
    return jsonb_build_object('ok', false, 'error', 'no user');
  end if;

  select referred_by into v_code from public.profiles where id = p_user_id;
  if v_code is null or length(trim(v_code)) = 0 then
    return jsonb_build_object('ok', false, 'reason', 'buyer not referred');
  end if;

  select candidate_id into v_cid
    from public.content_creator_social
   where upper(referral_code) = upper(trim(v_code))
   limit 1;
  if v_cid is null then
    return jsonb_build_object('ok', false, 'reason', 'not an influencer code');
  end if;

  -- Idempotent on the payment (preferred) or order id.
  if p_payment_id is not null and exists (
    select 1 from public.referral_earnings where payment_id = p_payment_id
  ) then
    return jsonb_build_object('ok', true, 'reason', 'already recorded');
  end if;
  if p_payment_id is null and p_order_id is not null and exists (
    select 1 from public.referral_earnings where order_id = p_order_id
  ) then
    return jsonb_build_object('ok', true, 'reason', 'already recorded');
  end if;

  v_comm := round(coalesce(p_amount, 0) * v_pct / 100.0, 2);

  insert into public.referral_earnings (
    referral_code, candidate_id, order_id, payment_id,
    purchase_amount, commission_pct, commission_amount, status
  ) values (
    upper(trim(v_code)), v_cid, p_order_id, p_payment_id,
    p_amount, v_pct, v_comm, 'pending'
  )
  on conflict (payment_id) where payment_id is not null do nothing;

  return jsonb_build_object('ok', true, 'commission', v_comm, 'candidate_id', v_cid);
exception when others then
  return jsonb_build_object('ok', false, 'error', sqlerrm);
end$function$

