$function$

CREATE OR REPLACE FUNCTION public.deduct_credits(p_user_id uuid, p_amount bigint, p_reason text, p_generation_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  current_credits bigint;
  new_credits     bigint;
begin
  if p_amount is null or p_amount < 0 then
    return jsonb_build_object('success', false, 'error', 'Invalid credit amount');
  end if;

  select credits into current_credits
  from public.profiles
  where id = p_user_id
  for update;

  if current_credits is null then
    return jsonb_build_object('success', false, 'error', 'Profile not found');
  end if;

  if current_credits < p_amount then
    return jsonb_build_object('success', false, 'error', 'Insufficient credits');
  end if;

  if p_amount = 0 then
    return jsonb_build_object('success', true, 'remaining_credits', current_credits);
  end if;

  update public.profiles
  set credits = credits - p_amount
  where id = p_user_id
  returning credits into new_credits;

  insert into public.credit_transactions
    (user_id, type, amount, delta, reason, generation_id, balance_after)
  values
    (p_user_id, 'deduct', p_amount, -p_amount,
     coalesce(nullif(trim(p_reason), ''), 'deduct'), p_generation_id, new_credits);

  return jsonb_build_object('success', true, 'remaining_credits', new_credits);
end;
$function$

CREATE OR REPLACE FUNCTION public.deduct_team_credits(p_team_id uuid, p_actor_id uuid, p_amount bigint, p_reason text DEFAULT 'generate'::text, p_generation_id text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_plan    TEXT;
  v_balance BIGINT;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'deduct_team_credits: amount must be positive';
  END IF;

  SELECT plan INTO v_plan FROM public.teams WHERE id = p_team_id FOR UPDATE;

  IF v_plan IN ('Empire', 'Founder', 'Unlimited') THEN
    SELECT credits INTO v_balance FROM public.teams WHERE id = p_team_id;
    INSERT INTO public.team_credit_transactions (team_id, actor_user_id, delta, reason, generation_id, balance_after)
    VALUES (p_team_id, p_actor_id, 0, p_reason || ':unlimited', p_generation_id, v_balance);
    RETURN v_balance;
  END IF;

  UPDATE public.teams
     SET credits    = credits - p_amount,
         updated_at = NOW()
   WHERE id = p_team_id
     AND credits >= p_amount
  RETURNING credits INTO v_balance;

  IF v_balance IS NULL THEN
    RETURN NULL; -- caller maps to HTTP 402
  END IF;

  INSERT INTO public.team_credit_transactions (team_id, actor_user_id, delta, reason, generation_id, balance_after)
  VALUES (p_team_id, p_actor_id, -p_amount, p_reason, p_generation_id, v_balance);

  RETURN v_balance;
END;
$function$

CREATE OR REPLACE FUNCTION public.refund_credits(p_user_id uuid, p_amount bigint, p_reason text DEFAULT 'refund'::text, p_generation_id text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_balance bigint;
begin
  if p_amount is null or p_amount <= 0 then
    raise exception 'refund_credits: amount must be positive';
  end if;

  update public.profiles
     set credits = credits + p_amount,
         updated_at = now()
   where id = p_user_id
   returning credits into v_balance;

  if v_balance is null then
    raise exception 'refund_credits: profile % not found', p_user_id;
  end if;

  insert into public.credit_transactions
    (user_id, type, amount, delta, reason, generation_id, balance_after)
  values
    (p_user_id, 'refund', p_amount, p_amount,
     p_reason, p_generation_id, v_balance);

  return v_balance;
end;
$function$

CREATE OR REPLACE FUNCTION public.refund_team_credits(p_team_id uuid, p_actor_id uuid, p_amount bigint, p_reason text DEFAULT 'refund'::text, p_generation_id text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
